using FluentValidation;using Microsoft.EntityFrameworkCore;using SchoolERP.Application.Abstractions;using SchoolERP.Application.Common.Extensions;using SchoolERP.Application.Common.Pagination;using SchoolERP.Application.Exceptions;using SchoolERP.Application.Features.Schools;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;namespace SchoolERP.Application.Features.Subjects;
public sealed class SubjectService(IApplicationDbContext db,ICurrentSchoolResolver current,IValidator<CreateSubjectRequest>cv,IValidator<UpdateSubjectRequest>uv,IValidator<ChangeSubjectCodeRequest>ccv,IValidator<SetClassSubjectsRequest>sv,TimeProvider clock):ISubjectService{
 public async Task<PagedResult<SubjectListItemDto>>ListAsync(GetSubjectsQuery r,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);if(r.AcademicYearId.HasValue&&!await db.AcademicYears.AsNoTracking().AnyAsync(x=>x.Id==r.AcademicYearId&&x.SchoolId==sid,ct))throw new ResourceNotFoundException("Academic year");var q=db.Subjects.AsNoTracking().Where(x=>x.SchoolId==sid).WhereIf(r.AcademicYearId.HasValue,x=>x.AcademicYearId==r.AcademicYearId).WhereIf(r.Status.HasValue,x=>x.Status==r.Status).WhereIf(r.Type.HasValue,x=>x.Type==r.Type).WhereIf(r.Category.HasValue,x=>x.Category==r.Category);if(!string.IsNullOrWhiteSpace(r.Search)){var t=r.Search.Trim().ToLower();q=q.Where(x=>x.Name.ToLower().Contains(t)||x.Code.ToLower().Contains(t)||(x.ShortName!=null&&x.ShortName.ToLower().Contains(t)));}var d=string.Equals(r.SortDirection,"desc",StringComparison.OrdinalIgnoreCase);q=(r.SortBy?.ToLowerInvariant(),d) switch{("name",false)=>q.OrderBy(x=>x.Name),("name",true)=>q.OrderByDescending(x=>x.Name),("code",false)=>q.OrderBy(x=>x.Code),("code",true)=>q.OrderByDescending(x=>x.Code),("status",false)=>q.OrderBy(x=>x.Status),("status",true)=>q.OrderByDescending(x=>x.Status),("createdat",true)=>q.OrderByDescending(x=>x.CreatedAt),_=>q.OrderBy(x=>x.DisplayOrder).ThenBy(x=>x.Name)};return await q.Select(x=>new SubjectListItemDto(x.Id,x.AcademicYearId,x.AcademicYear.Name,x.Name,x.Code,x.ShortName,x.Type,x.Category,x.DisplayOrder,x.CreditHours,x.WeeklyPeriods,x.Status,x.ClassSubjects.Count,x.CreatedAt,x.UpdatedAt)).ToPagedResultAsync(new(r.PageNumber,r.PageSize),ct);}
 public async Task<SubjectDetailsDto?>GetAsync(Guid id,CancellationToken ct=default){var sid=await current.ResolveAsync(ct);return await db.Subjects.AsNoTracking().Where(x=>x.Id==id&&x.SchoolId==sid).Select(x=>new SubjectDetailsDto(x.Id,x.AcademicYearId,x.AcademicYear.Name,x.AcademicYear.Code,x.Name,x.Code,x.ShortName,x.Type,x.Category,x.DisplayOrder,x.CreditHours,x.WeeklyPeriods,x.Status,x.Description,x.ActivatedAt,x.DeactivatedAt,x.ArchivedAt,x.CreatedAt,x.UpdatedAt)).SingleOrDefaultAsync(ct);}
 public async Task<SubjectDetailsDto>CreateAsync(CreateSubjectRequest r,CancellationToken ct=default){await cv.ValidateAndThrowAsync(r,ct);var sid=await current.ResolveAsync(ct);var school=await School(sid,ct);var y=await Year(r.AcademicYearId,sid,ct);await Unique(sid,y.Id,r.Code,r.Name,null,ct);var x=Subject.Create(school.TenantId,sid,y.Id,r.Name,r.Code,r.Type,r.DisplayOrder,r.ShortName,r.Category,r.CreditHours,r.WeeklyPeriods,r.Description,Now());db.Subjects.Add(x);await db.SaveChangesAsync(ct);return(await GetAsync(x.Id,ct))!;}public async Task<SubjectDetailsDto?>UpdateAsync(Guid id,UpdateSubjectRequest r,CancellationToken ct=default){await uv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await Parents(x,ct);await Unique(x.SchoolId,x.AcademicYearId,x.Code,r.Name,id,ct);x.UpdateDetails(r.Name,r.ShortName,r.Type,r.Category,r.DisplayOrder,r.CreditHours,r.WeeklyPeriods,r.Description,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}public async Task<SubjectDetailsDto?>ChangeCodeAsync(Guid id,ChangeSubjectCodeRequest r,CancellationToken ct=default){await ccv.ValidateAndThrowAsync(r,ct);var x=await Write(id,ct);if(x is null)return null;await Parents(x,ct);await Unique(x.SchoolId,x.AcademicYearId,r.Code,x.Name,id,ct);x.ChangeCode(r.Code,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public Task<SubjectDetailsDto?>ActivateAsync(Guid id,CancellationToken ct=default)=>Change(id,(x,n)=>x.Activate(n),false,ct);public Task<SubjectDetailsDto?>DeactivateAsync(Guid id,CancellationToken ct=default)=>Change(id,(x,n)=>x.Deactivate(n),false,ct);public Task<SubjectDetailsDto?>ArchiveAsync(Guid id,CancellationToken ct=default)=>Change(id,(x,n)=>x.Archive(n),true,ct);private async Task<SubjectDetailsDto?>Change(Guid id,Action<Subject,DateTime>a,bool archive,CancellationToken ct){var x=await Write(id,ct);if(x is null)return null;await Parents(x,ct);if(archive&&await db.ClassSubjects.AnyAsync(m=>m.SubjectId==id,ct))throw new SubjectHasClassAssignmentsException();a(x,Now());await db.SaveChangesAsync(ct);return await GetAsync(id,ct);}
 public async Task<IReadOnlyCollection<ClassSubjectDto>>GetClassSubjectsAsync(Guid classId,CancellationToken ct=default){var p=await Class(classId,ct);return await db.ClassSubjects.AsNoTracking().Where(x=>x.SchoolClassId==p.Id).OrderBy(x=>x.DisplayOrder).ThenBy(x=>x.Subject.Name).Select(x=>new ClassSubjectDto(x.SubjectId,x.Subject.Name,x.Subject.Code,x.Subject.Type,x.IsMandatory,x.DisplayOrder,x.Subject.Status)).ToListAsync(ct);}public async Task SetClassSubjectsAsync(Guid classId,SetClassSubjectsRequest r,CancellationToken ct=default){await sv.ValidateAndThrowAsync(r,ct);var p=await Class(classId,ct);var year=await Year(p.AcademicYearId,p.SchoolId,ct);if(p.Status is SchoolClassStatus.Inactive or SchoolClassStatus.Archived)throw new SubjectParentUnavailableException("Subject.ParentClassUnavailable");var ids=r.Items.Select(x=>x.SubjectId).ToArray();var subjects=await db.Subjects.Where(x=>ids.Contains(x.Id)&&x.SchoolId==p.SchoolId).ToListAsync(ct);if(subjects.Count!=ids.Length)throw new ResourceNotFoundException("Subject");if(subjects.Any(x=>x.AcademicYearId!=p.AcademicYearId))throw new ClassSubjectMismatchException();if(subjects.Any(x=>year.Status==AcademicYearStatus.Active?x.Status!=SubjectStatus.Active:x.Status is not(SubjectStatus.Draft or SubjectStatus.Active)))throw new SubjectParentUnavailableException("Only eligible subjects can be assigned.");var existing=await db.ClassSubjects.Where(x=>x.SchoolClassId==classId).ToListAsync(ct);db.ClassSubjects.RemoveRange(existing.Where(x=>!ids.Contains(x.SubjectId)));foreach(var i in r.Items){var m=existing.SingleOrDefault(x=>x.SubjectId==i.SubjectId);if(m is null)db.ClassSubjects.Add(ClassSubject.Create(p.TenantId,p.SchoolId,p.AcademicYearId,p.Id,i.SubjectId,i.IsMandatory,i.DisplayOrder));else m.Update(i.IsMandatory,i.DisplayOrder);}await db.SaveChangesAsync(ct);}public async Task AssignAsync(Guid c,Guid s,ClassSubjectAssignmentRequest r,CancellationToken ct=default){if(s!=r.SubjectId)throw new ClassSubjectMismatchException();var items=(await GetClassSubjectsAsync(c,ct)).Select(x=>new ClassSubjectAssignmentRequest(x.SubjectId,x.IsMandatory,x.DisplayOrder)).Where(x=>x.SubjectId!=s).Append(r).ToArray();await SetClassSubjectsAsync(c,new(items),ct);}public async Task RemoveAsync(Guid c,Guid s,CancellationToken ct=default){var p=await Class(c,ct);var m=await db.ClassSubjects.SingleOrDefaultAsync(x=>x.SchoolClassId==p.Id&&x.SubjectId==s,ct);if(m is not null){db.ClassSubjects.Remove(m);await db.SaveChangesAsync(ct);}}
 private async Task<School>School(Guid id,CancellationToken ct){var x=await db.Schools.AsNoTracking().SingleAsync(s=>s.Id==id,ct);if(x.Status is SchoolStatus.Suspended or SchoolStatus.Archived)throw new ParentNotOperationalException("School structure cannot be changed while suspended or archived.");return x;}private async Task<AcademicYear>Year(Guid id,Guid sid,CancellationToken ct){var y=await db.AcademicYears.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.SchoolId==sid,ct)??throw new ResourceNotFoundException("Academic year");if(y.Status is AcademicYearStatus.Closed or AcademicYearStatus.Archived)throw new SubjectParentUnavailableException();await School(sid,ct);return y;}private async Task<SchoolClass>Class(Guid id,CancellationToken ct){var sid=await current.ResolveAsync(ct);return await db.SchoolClasses.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==id&&x.SchoolId==sid,ct)??throw new ResourceNotFoundException("Class");}private async Task<Subject?>Write(Guid id,CancellationToken ct){var sid=await current.ResolveAsync(ct);return await db.Subjects.SingleOrDefaultAsync(x=>x.Id==id&&x.SchoolId==sid,ct);}private async Task Parents(Subject x,CancellationToken ct)=>_ = await Year(x.AcademicYearId,x.SchoolId,ct);private async Task Unique(Guid s,Guid y,string code,string name,Guid? except,CancellationToken ct){var c=Subject.NormalizeCode(code);var n=name.Trim().ToLower();if(await db.Subjects.AsNoTracking().AnyAsync(x=>x.SchoolId==s&&x.AcademicYearId==y&&x.Code==c&&(!except.HasValue||x.Id!=except),ct))throw new SubjectCodeConflictException();if(await db.Subjects.AsNoTracking().AnyAsync(x=>x.SchoolId==s&&x.AcademicYearId==y&&x.Name.ToLower()==n&&(!except.HasValue||x.Id!=except),ct))throw new SubjectNameConflictException();}private DateTime Now()=>clock.GetUtcNow().UtcDateTime;}
